function i(e){return Number(e||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"})}function a(e){return!e||e===0?"":Number(e).toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2})}function u(e){if(!e)return 0;let t=e.replace(/[R$\s]/g,"").trim();if(!t)return 0;t.includes(".")&&t.includes(",")?t=t.replace(/\./g,"").replace(",","."):t.includes(",")&&!t.includes(".")&&(t=t.replace(",","."));const n=parseFloat(t);return isNaN(n)?0:n}function c(e){return e?new Date(e+"T12:00").toLocaleDateString("pt-BR"):"—"}function s(){const e=new Date;return e.getFullYear()+"-"+String(e.getMonth()+1).padStart(2,"0")+"-"+String(e.getDate()).padStart(2,"0")}function o(e,t){if(!e||!t)return null;const n=new Date(e+"T12:00:00"),r=new Date(t+"T12:00:00");return Math.ceil((r.getTime()-n.getTime())/864e5)}function l(e){if(!e)return null;const t=new Date;t.setHours(0,0,0,0);const n=new Date(e+"T12:00");return Math.ceil((n.getTime()-t.getTime())/864e5)}export{o as a,a as b,l as d,c as f,s as i,i as m,u as p};
